#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int POT_PIN = A3;   
const byte segmentCodes[] = {
  0b11000000,  
  0b11111001,  
  0b10100100,  
  0b10110000,  
  0b10011001,  
  0b10010010,  
  0b10000010,  
  0b11111000,  
  0b10000000,  
  0b10010000,  
};

void setup();
void loop();
void displayNumber(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  displayNumber(0); 
}
void loop() {
  int potValue = analogRead(POT_PIN); 
  int mappedValue = map(potValue, 0, 1023, 0, 99); 
  displayNumber(mappedValue); 
  delay(200); 
}
void displayNumber(int number) {
  if (number < 0 || number > 99) {
    number = 0; 
  }
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
